import{_ as a,a as t,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"星际穿越","description":"地球的生存条件持续恶化，前飞行员库珀被卷入一项寻找人类新家园的太空任务。离开家人意味着他必须承受难以预测的时间差，而留在地球上的女儿墨菲也沿着自己的道路追问父亲留下的问题。","frontmatter":{"title":"星际穿越","description":"地球的生存条件持续恶化，前飞行员库珀被卷入一项寻找人类新家园的太空任务。离开家人意味着他必须承受难以预测的时间差，而留在地球上的女儿墨菲也沿着自己的道路追问父亲留下的问题。","media":{"category":"movies","year":2014,"doubanRating":9.4,"ratingCheckedAt":"2026-10-31","ratingSource":"https://movie.douban.com/top250","ratingSourceType":"豆瓣榜单"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 电影","summary":"地球的生存条件持续恶化，前飞行员库珀被卷入一项寻找人类新家园的太空任务。离开家人意味着他必须承受难以预测的时间差，而留在地球上的女儿墨菲也沿着自己的道路追问父亲留下的问题。","status":"active","related":[{"title":"肖申克的救赎","link":"/life/personal/media/movies/the-shawshank-redemption","kind":"影视导读","scope":"general","audience":"general"},{"title":"霸王别姬","link":"/life/personal/media/movies/farewell-my-concubine","kind":"影视导读","scope":"general","audience":"general"},{"title":"泰坦尼克号","link":"/life/personal/media/movies/titanic","kind":"影视导读","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"},{"title":"千与千寻","link":"/life/personal/media/movies/spirited-away","kind":"影视导读","scope":"general","audience":"general"},{"title":"美丽人生","link":"/life/personal/media/movies/life-is-beautiful","kind":"影视导读","scope":"general","audience":"general"},{"title":"这个杀手不太冷","link":"/life/personal/media/movies/leon","kind":"影视导读","scope":"general","audience":"general"},{"title":"盗梦空间","link":"/life/personal/media/movies/inception","kind":"影视导读","scope":"general","audience":"general"},{"title":"楚门的世界","link":"/life/personal/media/movies/the-truman-show","kind":"影视导读","scope":"general","audience":"general"},{"title":"辛德勒的名单","link":"/life/personal/media/movies/schindlers-list","kind":"影视导读","scope":"general","audience":"general"},{"title":"忠犬八公的故事","link":"/life/personal/media/movies/hachi-a-dogs-tale","kind":"影视导读","scope":"general","audience":"general"},{"title":"海上钢琴师","link":"/life/personal/media/movies/the-legend-of-1900","kind":"影视导读","scope":"general","audience":"general"},{"title":"疯狂动物城","link":"/life/personal/media/movies/zootopia","kind":"影视导读","scope":"general","audience":"general"},{"title":"三傻大闹宝莱坞","link":"/life/personal/media/movies/three-idiots","kind":"影视导读","scope":"general","audience":"general"},{"title":"机器人总动员","link":"/life/personal/media/movies/wall-e","kind":"影视导读","scope":"general","audience":"general"},{"title":"放牛班的春天","link":"/life/personal/media/movies/the-chorus","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"千与千寻","link":"/life/personal/media/movies/spirited-away"},"next":{"text":"美丽人生","link":"/life/personal/media/movies/life-is-beautiful"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"千与千寻","link":"/life/personal/media/movies/spirited-away"},"next":{"text":"美丽人生","link":"/life/personal/media/movies/life-is-beautiful"}},"headers":[],"relativePath":"life/personal/media/movies/interstellar.md","filePath":"life/personal/media/movies/interstellar.md"}'),l={name:"life/personal/media/movies/interstellar.md"};function n(d,e,o,s,p,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="星际穿越" tabindex="-1">星际穿越 <a class="header-anchor" href="#星际穿越" aria-label="Permalink to &quot;星际穿越&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">电影片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>Interstellar</td></tr><tr><td>年份 / 地区</td><td>2014 / 美国 / 英国 / 加拿大</td></tr><tr><td>类型</td><td>科幻 / 剧情 / 冒险</td></tr><tr><td>导演 / 主创</td><td>克里斯托弗·诺兰</td></tr><tr><td>主要演员 / 配音</td><td>马修·麦康纳、安妮·海瑟薇、杰西卡·查斯坦</td></tr><tr><td>篇幅 / 版本</td><td>约 169 分钟</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.4 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://movie.douban.com/top250" target="_blank" rel="noopener noreferrer">豆瓣电影 Top 250</a>（豆瓣榜单）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为本次查询可读取的豆瓣页面值，网页缓存可能滞后，不能保证与此刻实时值一致。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>基普·索恩在加州理工学院的公开介绍中说明，他与制片人琳达·奥布斯特于2006年提出了一些早期科学构想，后来由克里斯托弗与乔纳森·诺兰发展为电影。这个来历说明科学讨论进入了创作过程，但不能推出整部作品的情节都已获科学证明。<a href="https://www.caltech.edu/campus-life-events/calendar/physics-research-conference-104" target="_blank" rel="noopener noreferrer">索恩在加州理工的项目说明</a></p><p>影片的难点并非术语数量，而是它同时要求观众追随三种时间：飞船上的任务时间、地球家庭的成长时间，以及极端引力条件下不同地点的时间。三者不再整齐同步，情感冲突才获得独特形式。</p><h2 id="剧情介绍" tabindex="-1">剧情介绍 <a class="header-anchor" href="#剧情介绍" aria-label="Permalink to &quot;剧情介绍&quot;">​</a></h2><p>地球的生存条件持续恶化，前飞行员库珀被卷入一项寻找人类新家园的太空任务。离开家人意味着他必须承受难以预测的时间差，而留在地球上的女儿墨菲也沿着自己的道路追问父亲留下的问题。</p><p>影片同时推进宇宙探索和家庭关系：远处的一次决定，会在另一端变成多年等待。科学概念构成戏剧条件，父女之间的承诺、误解与信任则构成故事的情感核心。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-叙事与人物" tabindex="-1">1. 叙事与人物 <a class="header-anchor" href="#_1-叙事与人物" aria-label="Permalink to &quot;1. 叙事与人物&quot;">​</a></h3><p>把每次航行带来的时间代价放在人物关系中看，会比只记住技术名词更容易进入故事。视频留言与声音设计尤其强化了无法同步生活的痛感。</p><h3 id="_2-主题与表达" tabindex="-1">2. 主题与表达 <a class="header-anchor" href="#_2-主题与表达" aria-label="Permalink to &quot;2. 主题与表达&quot;">​</a></h3><p>影片用辽阔宇宙与狭小舱室形成对照，配乐常推动身体层面的紧张感。科学顾问参与不等于全部情节都是既有科学结论，后段仍有明确的科幻想象。</p><h2 id="人物与两代人的责任" tabindex="-1">人物与两代人的责任 <a class="header-anchor" href="#人物与两代人的责任" aria-label="Permalink to &quot;人物与两代人的责任&quot;">​</a></h2><p>库珀既渴望重新驾驶飞行器，也希望保护孩子；个人愿望与公共任务重合，让他的出发不能简单归类为牺牲或自私。墨菲则必须在父亲缺席的情况下成长，把愤怒、怀念与自己的研究生活放在一起。她不是等候被救的女儿，而是另一条行动线的承担者。</p><p>布兰德等同行者各自面对证据、情感和未知风险的冲突。远征中的专业判断并不会让人自动摆脱依恋与恐惧，电影也不断让看似理性的计划受到信息限制。可以逐次记录人物作决定时究竟知道什么，避免用后来揭晓的信息倒过来评判他们。</p><h2 id="一条方便初看的内容脉络" tabindex="-1">一条方便初看的内容脉络 <a class="header-anchor" href="#一条方便初看的内容脉络" aria-label="Permalink to &quot;一条方便初看的内容脉络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主要问题</th><th>观看重点</th></tr></thead><tbody><tr><td>地球与出发</td><td>谁离开、谁留下，任务为何紧迫</td><td>家庭关系及人类生存的双重责任</td></tr><tr><td>穿越与探索</td><td>有限燃料、时间与不完整资料怎样分配</td><td>每次选择的代价并不只发生在现场</td></tr><tr><td>地球研究与远征交错</td><td>两条路线怎样影响彼此</td><td>注意年龄变化、信息传递及等待</td></tr><tr><td>后段收束</td><td>早先的经验怎样获得新解释</td><td>留到看完再核对，不提前搜索结局图解</td></tr></tbody></table><h2 id="代表段落与视听方法" tabindex="-1">代表段落与视听方法 <a class="header-anchor" href="#代表段落与视听方法" aria-label="Permalink to &quot;代表段落与视听方法&quot;">​</a></h2><p>水面行星的危险不只来自巨浪，还来自时间成本；回到飞船后观看积累的家庭留言，使抽象差异变成人生已经过去。对接段落则通过旋转、节奏与声音制造身体紧张，让观众理解任务需要的精确性，无需先理解全部计算。</p><p>汉斯·季默的配乐中，持续音型和强烈的空间感常把“无法停止的时间”转化为听觉经验。观看时可注意音乐何时推动行动，何时留出沉默，让人的孤独重新出现。</p><h2 id="评价与科学讨论的边界" tabindex="-1">评价与科学讨论的边界 <a class="header-anchor" href="#评价与科学讨论的边界" aria-label="Permalink to &quot;评价与科学讨论的边界&quot;">​</a></h2><p>本片善于把宇宙尺度与私人情感相连，但后段用高度主观、富有戏剧性的方式处理未知，接受程度会因观众而异。将它评价为纯粹科学教材或纯粹家庭故事，都可能遗漏另一半。</p><p>看完后再把虫洞、引力时间差、黑洞成像与更具推测性的设定分别整理，比争论全片“科学或不科学”更有效。你可以对某个叙事转折保留意见，同时欣赏它如何让物理概念真正影响人物的生活。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢硬科幻元素、家庭主题和大银幕体验的人。建议在安静环境完整观看；首次观看不必先读物理解析，可看完后再区分科学基础与戏剧设定。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>库珀的选择同时承担了怎样的家庭责任和公共责任？时间差如何改变了“陪伴”的意义？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://movie.douban.com/top250" target="_blank" rel="noopener noreferrer">豆瓣电影 Top 250</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://movie.douban.com/subject/1889243/" target="_blank" rel="noopener noreferrer">《星际穿越》豆瓣条目</a>：版本与后续评分复核入口；部分条目可能要求验证。</li></ul><p><a href="./overview">返回电影片单</a> · <a href="./../overview">返回影视总览</a></p>',35)])])}const u=a(l,[["render",n]]);export{m as __pageData,u as default};
